// app.js — LivLens frontend. Loads areas.geojson (generated by scripts/build.py)
// and renders it on a Leaflet map.
//
// Two things are fully schema-agnostic — they read whatever columns exist in
// data/areas.csv without any code change here:
//   1. The side panel — renders every populated property on the clicked area.
//   2. The filters panel — auto-detects filterable columns (numeric or a
//      short list of repeated values) and builds a filter control for each.
//
// Filter model: every filter is marked "strict" or "negotiable". An area's
// computed colour is:
//   red    — fails at least one active STRICT filter (a dealbreaker)
//   yellow — passes all strict filters but fails an active negotiable one
//   green  — passes every active filter
// If no filters are active, the manual `status` column from the CSV is used
// instead, so the map still works with zero filters touched.

const STATUS_COLORS = {
  green: "#34d399",
  yellow: "#fbbf24",
  red: "#f87171",
  institutional: "#818cf8",
};

const HIDDEN_FIELDS = new Set(["lat", "lon", "radius_m"]);
const NON_FILTERABLE_FIELDS = new Set([
  "name", "city", "country", "status", "lat", "lon", "radius_m", "notes",
  // verdict is a personal, already-decided judgement call, not a filterable
  // attribute of the area itself — still shown in the side panel, just not
  // as a filter.
  "verdict",
]);
const MAX_CATEGORICAL_OPTIONS = 8;

// Known qualitative scales, ordered worst -> best, so a categorical filter's
// checkboxes list the most undesirable option first (e.g. "very loud" above
// "quiet"). Any column whose distinct values exactly match one of these
// scales (case-insensitively) is ordered this way; anything else falls back
// to plain alphabetical order, keeping the filter system schema-agnostic.
const KNOWN_SCALES = [
  ["very loud", "loud", "moderate", "quiet"],
  ["poor", "fair", "good", "very good"],
  ["low", "medium", "high"],
  ["avoid", "maybe", "shortlist"],
];

function orderCategoricalOptions(distinct) {
  const lower = distinct.map((v) => v.toLowerCase());
  const scale = KNOWN_SCALES.find(
    (s) => s.length === lower.length && s.every((v) => lower.includes(v))
  );
  if (!scale) return [...distinct].sort();
  return scale.map((v) => distinct.find((d) => d.toLowerCase() === v));
}

// zoomControl: false + added back top-right so it doesn't collide with the
// filters panel, which slides in from the top-left.
const map = L.map("map", { zoomControl: false }).setView([6.24, -75.58], 12);
L.control.zoom({ position: "topright" }).addTo(map);

// The UI chrome (header, panels) stays dark, but the basemap itself uses
// CARTO's bright "Voyager" tiles — a dark basemap made the street detail
// under each area's colour overlay nearly invisible.
L.tileLayer(
  "https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png",
  {
    attribution:
      '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
    maxZoom: 19,
  }
).addTo(map);

// ---------------------------------------------------------------------------
// Amenity point layers — toggleable map overlays (supermarkets, cafés, gyms,
// metro), not choropleth filters. Supermarket/gym are split per-brand so a
// single brand can be isolated (e.g. only Action Black gyms). Data comes
// from docs/amenity-points.json; no-ops quietly if that file is missing.
const GYM_BRAND_COLORS = {
  "Action Black": "#111827",
  "Smart Fit": "#f97316",
  Bodytech: "#38bdf8",
  Stark: "#a855f7",
  BFit: "#22c55e",
};
const GYM_DEFAULT_COLOR = "#94a3b8"; // unbranded/unmatched gyms
const GYM_DEFAULT_LABEL = "Other / unbranded";

const SUPERMARKET_BRAND_COLORS = {
  "Éxito": "#f97316",
  Carulla: "#16a34a",
  D1: "#ef4444",
  Ara: "#0ea5e9",
  Jumbo: "#eab308",
  "La Vaquita": "#ec4899",
  Euro: "#8b5cf6",
  Consumo: "#14b8a6",
};
const SUPERMARKET_DEFAULT_COLOR = "#94a3b8";
const SUPERMARKET_DEFAULT_LABEL = "Other / unbranded";

function amenityDivIcon(emoji, bgColor) {
  return L.divIcon({
    className: "amenity-marker",
    html: `<span class="amenity-marker-dot" style="background:${bgColor}">${emoji}</span>`,
    iconSize: [26, 26],
    iconAnchor: [13, 13],
    popupAnchor: [0, -13],
  });
}

// Groups a flat point array into one Leaflet marker per point, bucketed into
// a layerGroup per brand (falling back to a shared "Other" bucket) so each
// brand can be shown/hidden independently while the parent overlay is on.
function buildBrandedLayer(points, colors, defaultColor, defaultLabel, emoji) {
  const groups = {}; // brand label -> L.layerGroup
  for (const p of points) {
    const brand = p.brand || defaultLabel;
    const color = colors[p.brand] || defaultColor;
    const marker = L.marker([p.lat, p.lon], { icon: amenityDivIcon(emoji, color) }).bindPopup(
      escapeHtml(p.brand || p.name || defaultLabel)
    );
    if (!groups[brand]) groups[brand] = L.layerGroup();
    groups[brand].addLayer(marker);
  }
  const parent = L.layerGroup(Object.values(groups));
  return { parent, groups };
}

function buildAmenityLayers(points) {
  const cafeLayer = L.layerGroup(
    (points.cafe || []).map((p) =>
      L.marker([p.lat, p.lon], { icon: amenityDivIcon("\u2615", "#78350f") }).bindPopup(
        escapeHtml(p.name || "Café (unnamed on OpenStreetMap)")
      )
    )
  );

  const gym = buildBrandedLayer(points.gym || [], GYM_BRAND_COLORS, GYM_DEFAULT_COLOR, GYM_DEFAULT_LABEL, "\ud83c\udfcb");
  const supermarket = buildBrandedLayer(
    points.supermarket || [],
    SUPERMARKET_BRAND_COLORS,
    SUPERMARKET_DEFAULT_COLOR,
    SUPERMARKET_DEFAULT_LABEL,
    "\ud83d\uded2"
  );

  const metroLayer = L.layerGroup(
    (points.metro || []).map((p) =>
      L.marker([p.lat, p.lon], { icon: amenityDivIcon("\ud83d\ude87", "#2f9e44") }).bindPopup(
        escapeHtml(p.name || "Station")
      )
    )
  );

  return {
    overlays: {
      "\ud83d\uded2 Supermarkets": supermarket.parent,
      "\u2615 Cafés": cafeLayer,
      "\ud83c\udfcb Gyms": gym.parent,
      "\ud83d\ude87 Metro / Metrocable": metroLayer,
    },
    gymGroups: gym.groups,
    supermarketGroups: supermarket.groups,
  };
}

const GYM_LAYER_LABEL = "\ud83c\udfcb Gyms";
const SUPERMARKET_LAYER_LABEL = "\ud83d\uded2 Supermarkets";

// Renders a checkbox + colour dot per brand, wired to add/remove that
// brand's layerGroup from its parent overlay; "only" isolates one brand.
function renderBrandLegend(containerId, colors, defaultColor, defaultLabel, groups, parentLayer) {
  const container = document.getElementById(containerId);
  if (!container) return;
  const brandKeys = Object.keys(colors).filter((b) => groups[b]).concat(groups[defaultLabel] ? [defaultLabel] : []);
  container.innerHTML = brandKeys
    .map((brand) => {
      const color = colors[brand] || defaultColor;
      return `<label class="amenity-legend-item">
        <input type="checkbox" class="amenity-legend-checkbox" data-brand="${escapeHtml(brand)}" checked />
        <span class="amenity-legend-dot" style="background:${color}"></span>${escapeHtml(brand)}
        <button type="button" class="amenity-legend-only" data-brand="${escapeHtml(brand)}">only</button>
      </label>`;
    })
    .join("");

  container.querySelectorAll(".amenity-legend-checkbox").forEach((box) => {
    box.addEventListener("change", () => {
      const brand = box.dataset.brand;
      const group = groups[brand];
      if (!group) return;
      if (box.checked) parentLayer.addLayer(group);
      else parentLayer.removeLayer(group);
    });
  });
  container.querySelectorAll(".amenity-legend-only").forEach((btn) => {
    btn.addEventListener("click", () => {
      const onlyBrand = btn.dataset.brand;
      container.querySelectorAll(".amenity-legend-checkbox").forEach((box) => {
        const brand = box.dataset.brand;
        const group = groups[brand];
        const shouldShow = brand === onlyBrand;
        box.checked = shouldShow;
        if (!group) return;
        if (shouldShow) parentLayer.addLayer(group);
        else parentLayer.removeLayer(group);
      });
    });
  });
}

fetch("amenity-points.json")
  .then((res) => (res.ok ? res.json() : {}))
  .catch(() => ({}))
  .then((points) => {
    const { overlays, gymGroups, supermarketGroups } = buildAmenityLayers(points || {});
    L.control.layers(null, overlays, { collapsed: false, position: "topright" }).addTo(map);

    renderBrandLegend("gym-legend", GYM_BRAND_COLORS, GYM_DEFAULT_COLOR, GYM_DEFAULT_LABEL, gymGroups, overlays[GYM_LAYER_LABEL]);
    renderBrandLegend(
      "supermarket-legend",
      SUPERMARKET_BRAND_COLORS,
      SUPERMARKET_DEFAULT_COLOR,
      SUPERMARKET_DEFAULT_LABEL,
      supermarketGroups,
      overlays[SUPERMARKET_LAYER_LABEL]
    );

    const gymLegend = document.getElementById("gym-legend");
    const supermarketLegend = document.getElementById("supermarket-legend");
    map.on("overlayadd", (e) => {
      if (e.name === GYM_LAYER_LABEL && gymLegend) gymLegend.style.display = "flex";
      if (e.name === SUPERMARKET_LAYER_LABEL && supermarketLegend) supermarketLegend.style.display = "flex";
    });
    map.on("overlayremove", (e) => {
      if (e.name === GYM_LAYER_LABEL && gymLegend) gymLegend.style.display = "none";
      if (e.name === SUPERMARKET_LAYER_LABEL && supermarketLegend) supermarketLegend.style.display = "none";
    });
  });

const panel = document.getElementById("panel");
const panelContent = document.getElementById("panel-content");
const panelClose = document.getElementById("panel-close");
const emptyHint = document.getElementById("empty-hint");
const filtersPanel = document.getElementById("filters-panel");
const filtersContent = document.getElementById("filters-content");
const filtersToggle = document.getElementById("filters-toggle");
const filtersReset = document.getElementById("filters-reset");

const activeStatuses = new Set(["green", "yellow", "red"]);
let geoLayer = null;
let filterDefs = [];
let filterState = {};

function prettifyLabel(key) {
  return key
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .replace(/\bUsd\b/i, "USD")
    .replace(/\bM\b/, "m");
}

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

// ---------------------------------------------------------------------------
// Filter engine
// ---------------------------------------------------------------------------

// Numeric filter direction. Most numeric columns are "lower is better" (a
// threshold slider means "at most this much") — but some are inverted, where
// *higher* is better (e.g. a warmer minimum temperature, or a count/density
// of nearby amenities). Rather than a hardcoded column list, this is a
// documented naming convention (see AGENTS.md) so future generated columns
// (e.g. supermarket counts per km²) get the right direction automatically
// without a code change here.
const GREATER_IS_BETTER_SUFFIXES = ["_min_c", "_count_1km", "_brands_1km", "_per_km2"];

function filterDirection(key) {
  return GREATER_IS_BETTER_SUFFIXES.some((suffix) => key.endsWith(suffix)) ? "gte" : "lte";
}

function buildFilterDefinitions(features) {
  const fieldValues = {};
  features.forEach((f) => {
    Object.entries(f.properties).forEach(([key, value]) => {
      if (NON_FILTERABLE_FIELDS.has(key)) return;
      if (value === undefined || value === null || value === "") return;
      (fieldValues[key] = fieldValues[key] || []).push(String(value));
    });
  });

  const defs = [];
  Object.entries(fieldValues).forEach(([key, values]) => {
    const isNumeric = values.every((v) => v !== "" && !isNaN(parseFloat(v)) && isFinite(v));
    if (isNumeric) {
      const nums = values.map(Number);
      const min = Math.min(...nums);
      const max = Math.max(...nums);
      if (min === max) return; // no variation to filter on
      defs.push({ key, type: "numeric", label: prettifyLabel(key), min, max, direction: filterDirection(key) });
    } else {
      const distinct = orderCategoricalOptions([...new Set(values)]);
      if (distinct.length > 1 && distinct.length <= MAX_CATEGORICAL_OPTIONS) {
        defs.push({ key, type: "categorical", label: prettifyLabel(key), options: distinct });
      }
    }
  });
  return defs.sort((a, b) => a.label.localeCompare(b.label));
}

function initFilterState(defs) {
  const state = {};
  defs.forEach((def) => {
    if (def.type === "numeric") {
      // Default to the non-restrictive end: for "lower is better" (lte) that's
      // the max value (no area excluded); for "higher is better" (gte) it's
      // the min value.
      const defaultThreshold = def.direction === "gte" ? def.min : def.max;
      state[def.key] = { threshold: defaultThreshold, strict: false };
    } else {
      state[def.key] = { selected: new Set(def.options), strict: false };
    }
  });
  return state;
}

function isFilterActive(def) {
  const s = filterState[def.key];
  if (def.type === "numeric") {
    return def.direction === "gte" ? s.threshold > def.min : s.threshold < def.max;
  }
  return s.selected.size < def.options.length;
}

function evaluateFilter(def, rawValue) {
  if (rawValue === undefined || rawValue === null || rawValue === "") return true; // unknown data doesn't disqualify
  const s = filterState[def.key];
  if (def.type === "numeric") {
    return def.direction === "gte" ? parseFloat(rawValue) >= s.threshold : parseFloat(rawValue) <= s.threshold;
  }
  return s.selected.has(String(rawValue));
}

function computeColor(feature) {
  const status = (feature.properties.status || "").toLowerCase();
  // Institutional zones (universities, parks, military bases, etc.) aren't
  // residential candidates — they're always this colour regardless of any
  // active filter, and are only ever shown via their own toggle chip.
  if (status === "institutional") return STATUS_COLORS.institutional;

  const manualColor = STATUS_COLORS[status] || "#64748b";
  const activeDefs = filterDefs.filter(isFilterActive);
  if (activeDefs.length === 0) return manualColor;

  let dealbreaker = false;
  let softFail = false;
  for (const def of activeDefs) {
    const pass = evaluateFilter(def, feature.properties[def.key]);
    if (!pass) {
      if (filterState[def.key].strict) dealbreaker = true;
      else softFail = true;
    }
  }
  if (dealbreaker) return STATUS_COLORS.red;
  if (softFail) return STATUS_COLORS.yellow;
  return STATUS_COLORS.green;
}

function colorToStatusName(color) {
  return Object.keys(STATUS_COLORS).find((k) => STATUS_COLORS[k] === color) || null;
}

function renderFiltersPanel() {
  if (filterDefs.length === 0) {
    filtersContent.innerHTML = `<p class="filters-empty">No filterable columns found in areas.csv.</p>`;
    return;
  }

  filtersContent.innerHTML = filterDefs
    .map((def) => {
      const s = filterState[def.key];
      const active = isFilterActive(def);
      let controlHtml;
      if (def.type === "numeric") {
        const symbol = def.direction === "gte" ? "\u2265" : "\u2264";
        controlHtml = `
          <input type="range" min="${def.min}" max="${def.max}" value="${s.threshold}" data-key="${def.key}" class="filter-range" />
          <div class="filter-range-value">${symbol} ${s.threshold}</div>`;
      } else {
        controlHtml = def.options
          .map(
            (opt) => `
          <label class="filter-option">
            <input type="checkbox" data-key="${def.key}" data-option="${escapeHtml(opt)}" ${s.selected.has(opt) ? "checked" : ""} />
            ${escapeHtml(opt)}
          </label>`
          )
          .join("");
      }
      return `
        <div class="filter-row ${active ? "active" : ""}">
          <div class="filter-row-header">
            <span class="filter-label">${escapeHtml(def.label)}</span>
            <label class="strict-toggle" title="Strict = a dealbreaker (colours the area red). Negotiable = a soft mismatch (colours it yellow).">
              <input type="checkbox" data-strict-key="${def.key}" ${s.strict ? "checked" : ""} />
              Strict
            </label>
          </div>
          <div class="filter-control">${controlHtml}</div>
        </div>`;
    })
    .join("");

  filtersContent.querySelectorAll(".filter-range").forEach((el) => {
    // IMPORTANT: do not call renderFiltersPanel() (a full innerHTML rebuild)
    // from here. That destroys and recreates this very <input> mid-drag,
    // which kills the browser's native drag/touch gesture — janky on
    // desktop, completely broken on mobile. Patch just the bits that need
    // to change instead.
    el.addEventListener("input", () => {
      const def = filterDefs.find((d) => d.key === el.dataset.key);
      filterState[def.key].threshold = Number(el.value);
      const symbol = def.direction === "gte" ? "\u2265" : "\u2264";
      const valueEl = el.parentElement.querySelector(".filter-range-value");
      if (valueEl) valueEl.textContent = `${symbol} ${el.value}`;
      const row = el.closest(".filter-row");
      if (row) row.classList.toggle("active", isFilterActive(def));
      applyStyles();
    });
  });
  filtersContent.querySelectorAll('input[type="checkbox"][data-key]').forEach((el) => {
    el.addEventListener("change", () => {
      const { key, option } = el.dataset;
      const selected = filterState[key].selected;
      if (el.checked) selected.add(option);
      else selected.delete(option);
      renderFiltersPanel();
      applyStyles();
    });
  });
  filtersContent.querySelectorAll("input[data-strict-key]").forEach((el) => {
    el.addEventListener("change", () => {
      filterState[el.dataset.strictKey].strict = el.checked;
      applyStyles();
    });
  });
}

function resetFilters() {
  filterState = initFilterState(filterDefs);
  renderFiltersPanel();
  applyStyles();
}

filtersToggle.addEventListener("click", () => {
  filtersPanel.classList.toggle("open");
});
filtersReset.addEventListener("click", resetFilters);

// ---------------------------------------------------------------------------
// Map styling + side panel
// ---------------------------------------------------------------------------

function styleFeature(feature) {
  return {
    fillColor: computeColor(feature),
    fillOpacity: 0.5,
    color: "rgba(15, 23, 42, 0.65)",
    weight: 1.5,
  };
}

function applyStyles() {
  if (!geoLayer) return;
  geoLayer.eachLayer((layer) => {
    const color = computeColor(layer.feature);
    const statusName = colorToStatusName(color);
    const visible = !statusName || activeStatuses.has(statusName);
    layer.setStyle({
      fillColor: color,
      fillOpacity: visible ? 0.5 : 0,
      opacity: visible ? 1 : 0,
      weight: 1.5,
    });
    layer.options.interactive = visible;
  });
}

function renderPanel(properties) {
  const status = (properties.status || "").toLowerCase();
  const name = properties.name || "Unnamed area";
  const city = properties.city || "";
  const country = properties.country || "";

  let html = `<h2>${escapeHtml(name)}</h2>`;
  html += `<div class="subtitle">${escapeHtml([city, country].filter(Boolean).join(", "))}</div>`;
  if (status) {
    html += `<div class="status-badge ${status}">${escapeHtml(status)}</div>`;
  }

  for (const [key, value] of Object.entries(properties)) {
    if (HIDDEN_FIELDS.has(key)) continue;
    if (["name", "city", "country", "status"].includes(key)) continue;
    if (value === undefined || value === null || value === "") continue;
    html += `<div class="field"><div class="label">${escapeHtml(prettifyLabel(key))}</div><div class="value">${escapeHtml(String(value))}</div></div>`;
  }

  panelContent.innerHTML = html;
}

function openPanel(properties) {
  renderPanel(properties);
  panel.classList.add("open");
  emptyHint.style.display = "none";
  const slug = (properties.name || "").toLowerCase().replace(/\s+/g, "-");
  if (slug) history.replaceState(null, "", `#${slug}`);
}

function closePanel() {
  panel.classList.remove("open");
  history.replaceState(null, "", location.pathname);
}

panelClose.addEventListener("click", closePanel);
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") closePanel();
});

document.querySelectorAll(".filter-chip").forEach((chip) => {
  chip.addEventListener("click", () => {
    const status = chip.dataset.status;
    if (activeStatuses.has(status)) {
      activeStatuses.delete(status);
      chip.classList.add("off");
    } else {
      activeStatuses.add(status);
      chip.classList.remove("off");
    }
    applyStyles();
  });
});

fetch("areas.geojson")
  .then((res) => res.json())
  .then((data) => {
    if (!data.features || data.features.length === 0) {
      emptyHint.textContent = "No areas yet — add a row to data/areas.csv";
      emptyHint.style.display = "block";
      return;
    }

    filterDefs = buildFilterDefinitions(data.features);
    filterState = initFilterState(filterDefs);
    renderFiltersPanel();

    geoLayer = L.geoJSON(data, {
      style: styleFeature,
      onEachFeature: (feature, layer) => {
        layer.on("mouseover", () => layer.setStyle({ weight: 3 }));
        layer.on("mouseout", () => layer.setStyle({ weight: 1.5 }));
        layer.on("click", () => {
          const statusName = colorToStatusName(computeColor(feature));
          if (!statusName || activeStatuses.has(statusName)) openPanel(feature.properties);
        });
      },
    }).addTo(map);

    // styleFeature() (used above) doesn't know about chip visibility state —
    // apply it once now so anything hidden by default (e.g. Institutional)
    // starts hidden instead of flashing visible until the next interaction.
    applyStyles();

    map.fitBounds(geoLayer.getBounds(), { padding: [20, 20] });
    emptyHint.style.display = "block";

    // Deep-link support: #laureles opens that area's panel on load.
    const slug = location.hash.replace("#", "");
    if (slug) {
      const match = data.features.find(
        (f) => (f.properties.name || "").toLowerCase().replace(/\s+/g, "-") === slug
      );
      if (match) openPanel(match.properties);
    }
  })
  .catch((err) => {
    emptyHint.textContent = "Could not load areas.geojson — run scripts/build.py";
    emptyHint.style.display = "block";
    console.error(err);
  });
